155	func (s *mcpServer) sendResponse(id *json.RawMessage, result any) {
156		if id == nil || string(*id) == "null" {
157			// Per JSON-RPC 2.0 and MCP spec, never send a response to a notification
158			return
159		}
160		resp := jsonRPCResponse{
161			JSONRPC: "2.0",
162			ID:      id,
163			Result:  result,
164		}
165		data, _ := json.Marshal(resp)
166		s.mu.Lock()
167		defer s.mu.Unlock()
168		_, _ = s.writer.Write(append(data, '\n'))
169	}
170	
171	func (s *mcpServer) sendError(id *json.RawMessage, code int, message string) {
172		if (id == nil || string(*id) == "null") && code != -32700 {
173			// Per JSON-RPC 2.0 and MCP spec, never reply to a notification
174			return
175		}
176		resp := jsonRPCResponse{
177			JSONRPC: "2.0",
178			ID:      id,
179			Error: &rpcError{
180				Code:    code,
181				Message: message,
182			},
183		}
184		data, _ := json.Marshal(resp)
185		s.mu.Lock()
186		defer s.mu.Unlock()
187		_, _ = s.writer.Write(append(data, '\n'))
188	}
