283	func (s *mcpServer) resolveBundleDir(callParams mcpToolCallParams) (string, error) {
284		target, err := getStringArg(callParams.Arguments, "bundle", 1000, false)
285		if err != nil {
286			return "", err
287		}
288		target = strings.TrimSpace(target)
289	
290		if target == "" {
291			if s.bundleDir != "" && s.bundleDir != "." {
292				target = s.bundleDir
293			} else if info, err := os.Stat("knowledge"); err == nil && info.IsDir() {
294				target = "knowledge"
295			} else {
296				target = "."
297			}
298		}
299	
300		normTarget := strings.ReplaceAll(target, "\\", "/")
301	
302		// Confinement check: if s.rootDir is configured, target must stay within s.rootDir
303		if s.rootDir != "" {
304			absRoot, err := filepath.EvalSymlinks(s.rootDir)
305			if err != nil {
306				absRoot, err = filepath.Abs(s.rootDir)
307				if err != nil {
308					return "", fmt.Errorf("invalid server root directory: %w", err)
309				}
310			} else {
311				absRoot, _ = filepath.Abs(absRoot)
312			}
313	
314			var absTarget string
315			if IsAbsPath(normTarget) {
316				absTarget = normTarget
317			} else {
318				absTarget = filepath.Join(s.rootDir, filepath.FromSlash(normTarget))
319			}
320	
321			// Walk up to find the closest ancestor that exists and evaluate its symlinks
322			curr := absTarget
323			var missingParts []string
324			for {
325				_, lstatErr := os.Lstat(curr)
326				if lstatErr == nil {
327					break
328				}
329				missingParts = append([]string{filepath.Base(curr)}, missingParts...)
330				parent := filepath.Dir(curr)
331				if parent == curr {
332					break
333				}
334				curr = parent
335			}
336	
337			realCurr, err := filepath.EvalSymlinks(curr)
338			if err != nil {
339				return "", fmt.Errorf("failed to resolve bundle path %q: %w", target, err)
340			}
341			realCurr, err = filepath.Abs(realCurr)
342			if err != nil {
343				return "", err
344			}
345	
346			parts := append([]string{realCurr}, missingParts...)
347			realTarget := filepath.Join(parts...)
348	
349			rel, err := filepath.Rel(absRoot, realTarget)
350			normRel := strings.ReplaceAll(rel, "\\", "/")
351			if err != nil || rel == ".." || normRel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || strings.HasPrefix(normRel, "../") {
352				return "", fmt.Errorf("path traversal denied: bundle directory %q escapes server root %q", target, s.rootDir)
353			}
354	
355			return realTarget, nil
356		}
357	
358		return target, nil
359	}
