409	func (s *mcpServer) handleToolCall(req jsonRPCRequest) {
410		var callParams mcpToolCallParams
411		if err := json.Unmarshal(req.Params, &callParams); err != nil {
412			s.sendError(req.ID, -32602, "Invalid params")
413			return
414		}
415	
416		if callParams.Arguments == nil {
417			callParams.Arguments = make(map[string]any)
418		}
419	
420		bundleDir, err := s.resolveBundleDir(callParams)
421		if err != nil {
422			s.sendToolResult(req.ID, fmt.Sprintf("Path traversal denied: %v", err), nil, true)
423			return
424		}
425	
426		b, err := LoadBundle(bundleDir)
427		if err != nil {
428			if callParams.Name != "okf_search" && callParams.Name != "okf_show" {
429				s.sendToolResult(req.ID, fmt.Sprintf("Failed to load bundle from %q: %v", bundleDir, err), nil, true)
430				return
431			}
432		}
433	
434		switch callParams.Name {
435		case "okf_search":
436			query, err := getStringArg(callParams.Arguments, "query", 10000, false)
437			if err != nil {
438				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
439				return
440			}
441			scope, err := getStringArg(callParams.Arguments, "scope", 100, false)
442			if err != nil {
443				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
444				return
445			}
446			forPath, err := getStringArg(callParams.Arguments, "for_path", 1000, false)
447			if err != nil {
448				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
449				return
450			}
451			filter, err := getStringArg(callParams.Arguments, "filter", 1000, false)
452			if err != nil {
453				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
454				return
455			}
456			staleWithinStr, err := getStringArg(callParams.Arguments, "stale_within", 100, false)
457			if err != nil {
458				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
459				return
460			}
461			var staleWithin time.Duration
462			if staleWithinStr != "" {
463				d, err := ParseRelativeDuration(staleWithinStr)
464				if err != nil {
465					s.sendToolResult(req.ID, fmt.Sprintf("Invalid stale_within duration: %v", err), nil, true)
466					return
467				}
468				staleWithin = d
469			}
470			limit := 10
471			if l, ok := callParams.Arguments["limit"].(float64); ok {
472				if l > 0 && l <= 100 {
473					limit = int(l)
474				} else if l > 100 {
475					limit = 100
476				}
477			}
478	
479			vendorRoot := filepath.Join(".okf", "vendor")
480			if s.rootDir != "" {
481				cand := filepath.Join(s.rootDir, ".okf", "vendor")
482				if info, err := os.Stat(cand); err == nil && info.IsDir() {
483					vendorRoot = cand
484				}
485			}
486	
487			results, err := SearchLayered(LayeredSearchOptions{
488				BundleDir:  bundleDir,
489				VendorRoot: vendorRoot,
490				UserDir:    ResolveUserDir(),
491				SystemDir:  ResolveSystemDir(),
492				Scope:      scope,
493				SearchOpts: SearchOptions{
494					Query:       query,
495					TargetPath:  forPath,
496					Limit:       limit,
497					Filter:      filter,
498					StaleWithin: staleWithin,
499				},
500			})
501			if err != nil {
502				s.sendToolResult(req.ID, fmt.Sprintf("Search error: %v", err), nil, true)
503				return
504			}
505			if results == nil {
506				results = []SearchResult{}
507			}
508			resJSON, _ := json.Marshal(results)
509			envelope := map[string]any{"results": results}
510			s.sendToolResult(req.ID, string(resJSON), envelope, false)
511	
512		case "okf_show":
513			conceptID, err := getStringArg(callParams.Arguments, "concept_id", 1000, true)
514			if err != nil {
515				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
516				return
517			}
518			conceptID = strings.TrimSpace(conceptID)
519	
520			vendorRoot := filepath.Join(".okf", "vendor")
521			if s.rootDir != "" {
522				cand := filepath.Join(s.rootDir, ".okf", "vendor")
523				if info, err := os.Stat(cand); err == nil && info.IsDir() {
524					vendorRoot = cand
525				}
526			}
527	
528			res, err := ResolveScopedConcept(conceptID, bundleDir, vendorRoot, ResolveUserDir(), ResolveSystemDir())
529			if err != nil {
530				s.sendToolResult(req.ID, fmt.Sprintf("%v", err), nil, true)
531				return
532			}
533			resJSON, _ := json.Marshal(res)
534			s.sendToolResult(req.ID, string(resJSON), res, false)
535	
536		case "okf_validate":
537			strict := true
538			if sVal, ok := callParams.Arguments["strict"].(bool); ok {
539				strict = sVal
540			}
541			stale := false
542			if stVal, ok := callParams.Arguments["stale"].(bool); ok {
543				stale = stVal
544			}
545			staleWithinStr, err := getStringArg(callParams.Arguments, "stale_within", 100, false)
546			if err != nil {
547				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
548				return
549			}
550			var staleWithin time.Duration
551			if staleWithinStr != "" {
552				d, err := ParseRelativeDuration(staleWithinStr)
553				if err != nil {
554					s.sendToolResult(req.ID, fmt.Sprintf("Invalid stale_within duration: %v", err), nil, true)
555					return
556				}
557				staleWithin = d
558			}
559			res := Validate(b, ValidateOptions{Strict: strict, Drift: true, Stale: stale, StaleWithin: staleWithin})
560			if res.Errors == nil {
561				res.Errors = []string{}
562			}
563			if res.Warnings == nil {
564				res.Warnings = []string{}
565			}
566			if res.GateFindings == nil {
567				res.GateFindings = []string{}
568			}
569			if res.BrokenLinks == nil {
570				res.BrokenLinks = []BrokenLink{}
571			}
572			if res.Orphans == nil {
573				res.Orphans = []string{}
574			}
575			resJSON, _ := json.Marshal(res)
576			s.sendToolResult(req.ID, string(resJSON), res, false)
577	
578		case "okf_create":
579			conceptID, err := getStringArg(callParams.Arguments, "concept_id", 1000, true)
580			if err != nil {
581				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
582				return
583			}
584			conceptID = strings.TrimSpace(conceptID)
585			if err := ValidateConceptID(conceptID); err != nil {
586				s.sendToolResult(req.ID, fmt.Sprintf("Invalid concept_id: %v", err), nil, true)
587				return
588			}
589			conceptType, err := getStringArg(callParams.Arguments, "type", 1000, true)
590			if err != nil {
591				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
592				return
593			}
594			conceptType = strings.TrimSpace(conceptType)
595			if conceptType == "" {
596				s.sendToolResult(req.ID, "Invalid type: concept type cannot be empty or whitespace", nil, true)
597				return
598			}
599			title, err := getStringArg(callParams.Arguments, "title", 1000, true)
600			if err != nil {
601				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
602				return
603			}
604			if strings.TrimSpace(title) == "" {
605				s.sendToolResult(req.ID, "Invalid title: concept title cannot be empty or whitespace", nil, true)
606				return
607			}
608			desc, err := getStringArg(callParams.Arguments, "description", 1000, false)
609			if err != nil {
610				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
611				return
612			}
613			body, err := getStringArg(callParams.Arguments, "body", 1024*1024, false)
614			if err != nil {
615				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
616				return
617			}
618			status := "stable"
619			if _, exists := callParams.Arguments["status"]; exists {
620				status, err = getMutationStatus(callParams.Arguments)
621				if err != nil {
622					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
623					return
624				}
625			}
626			var tags []string
627			if _, exists := callParams.Arguments["tags"]; exists {
628				tags, err = getTagsArg(callParams.Arguments)
629				if err != nil {
630					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
631					return
632				}
633			}
634	
635			cleanID := strings.TrimSuffix(conceptID, ".md")
636			c := &Concept{
637				ID:          cleanID,
638				Path:        cleanID + ".md",
639				Type:        conceptType,
640				Title:       strings.TrimSpace(title),
641				Description: desc,
642				Body:        body,
643				Status:      status,
644				Tags:        tags,
645			}
646	
647			if err := SaveConcept(bundleDir, c, SaveOptions{
648				IsNew:     true,
649				AutoLog:   true,
650				AutoIndex: true,
651				Actor:     "agent/mcp",
652			}); err != nil {
653				s.sendToolResult(req.ID, fmt.Sprintf("Failed to save concept: %v", err), nil, true)
654				return
655			}
656	
657			msg := fmt.Sprintf("Successfully created concept %s in %s", c.Path, bundleDir)
658			structured := map[string]any{
659				"success":    true,
660				"concept_id": c.ID,
661				"path":       c.Path,
662				"bundle":     bundleDir,
663				"message":    msg,
664			}
665			s.sendToolResult(req.ID, msg, structured, false)
666	
667		case "okf_update":
668			conceptID, err := getStringArg(callParams.Arguments, "concept_id", 1000, true)
669			if err != nil {
670				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
671				return
672			}
673			conceptID = strings.TrimSpace(conceptID)
674			if err := ValidateConceptID(conceptID); err != nil {
675				s.sendToolResult(req.ID, fmt.Sprintf("Invalid concept_id: %v", err), nil, true)
676				return
677			}
678			cleanID := strings.TrimSuffix(conceptID, ".md")
679			if _, ok := b.Concepts[cleanID]; !ok {
680				s.sendToolResult(req.ID, fmt.Sprintf("Concept '%s' not found in %s", cleanID, bundleDir), nil, true)
681				return
682			}
683	
684			_, hasType := callParams.Arguments["type"]
685			var conceptType string
686			if hasType {
687				conceptType, err = getStringArg(callParams.Arguments, "type", 1000, true)
688				if err != nil {
689					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
690					return
691				}
692				if strings.TrimSpace(conceptType) == "" {
693					s.sendToolResult(req.ID, "Invalid type: concept type cannot be empty or whitespace", nil, true)
694					return
695				}
696				conceptType = strings.TrimSpace(conceptType)
697			}
698			_, hasStatus := callParams.Arguments["status"]
699			var status string
700			if hasStatus {
701				status, err = getMutationStatus(callParams.Arguments)
702				if err != nil {
703					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
704					return
705				}
706			}
707			_, hasTags := callParams.Arguments["tags"]
708			var tags []string
709			if hasTags {
710				tags, err = getTagsArg(callParams.Arguments)
711				if err != nil {
712					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
713					return
714				}
715			}
716			_, hasTitle := callParams.Arguments["title"]
717			var title string
718			if hasTitle {
719				title, err = getStringArg(callParams.Arguments, "title", 1000, true)
720				if err != nil {
721					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
722					return
723				}
724				if strings.TrimSpace(title) == "" {
725					s.sendToolResult(req.ID, "Invalid title: concept title cannot be empty or whitespace", nil, true)
726					return
727				}
728				title = strings.TrimSpace(title)
729			}
730			_, hasDesc := callParams.Arguments["description"]
731			var desc string
732			if hasDesc {
733				desc, err = getStringArg(callParams.Arguments, "description", 1000, false)
734				if err != nil {
735					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
736					return
737				}
738			}
739			_, hasBody := callParams.Arguments["body"]
740			var body string
741			if hasBody {
742				body, err = getStringArg(callParams.Arguments, "body", 1024*1024, false)
743				if err != nil {
744					s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
745					return
746				}
747			}
748	
749			updated, err := UpdateConcept(bundleDir, cleanID, SaveOptions{
750				IsNew:     false,
751				AutoLog:   true,
752				AutoIndex: true,
753				Actor:     "agent/mcp",
754			}, func(c *Concept) error {
755				if hasType {
756					c.Type = conceptType
757				}
758				if hasStatus {
759					c.Status = status
760				}
761				if hasTags {
762					c.Tags = tags
763				}
764				if hasTitle {
765					c.Title = title
766				}
767				if hasDesc {
768					c.Description = desc
769				}
770				if hasBody {
771					c.Body = body
772				}
773				return nil
774			})
775			if err != nil {
776				if errors.Is(err, ErrConceptNotFound) {
777					s.sendToolResult(req.ID, fmt.Sprintf("Concept '%s' not found in %s", cleanID, bundleDir), nil, true)
778					return
779				}
780				s.sendToolResult(req.ID, fmt.Sprintf("Failed to update concept: %v", err), nil, true)
781				return
782			}
783	
784			msg := fmt.Sprintf("Successfully updated concept %s in %s", updated.Path, bundleDir)
785			structured := map[string]any{
786				"success":    true,
787				"concept_id": updated.ID,
788				"path":       updated.Path,
789				"bundle":     bundleDir,
790				"message":    msg,
791			}
792			s.sendToolResult(req.ID, msg, structured, false)
793	
794		case "okf_relate":
795			srcID, err := getStringArg(callParams.Arguments, "source_id", 1000, true)
796			if err != nil {
797				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
798				return
799			}
800			tgtID, err := getStringArg(callParams.Arguments, "target_id", 1000, true)
801			if err != nil {
802				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
803				return
804			}
805			desc, err := getStringArg(callParams.Arguments, "description", 1000, false)
806			if err != nil {
807				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
808				return
809			}
810	
811			if err := RelateConcepts(bundleDir, srcID, tgtID, desc, "agent/mcp"); err != nil {
812				s.sendToolResult(req.ID, fmt.Sprintf("Failed to relate concepts: %v", err), nil, true)
813				return
814			}
815	
816			msg := fmt.Sprintf("Successfully linked '%s' -> '%s' in %s", srcID, tgtID, bundleDir)
817			structured := map[string]any{
818				"success":   true,
819				"source_id": srcID,
820				"target_id": tgtID,
821				"bundle":    bundleDir,
822				"message":   msg,
823			}
824			s.sendToolResult(req.ID, msg, structured, false)
825	
826		default:
827			s.sendToolResult(req.ID, fmt.Sprintf("Unknown tool: %s", callParams.Name), nil, true)
828		}
829	}
