			if err != nil {
				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
				return
			}
		}

		cleanID := strings.TrimSuffix(conceptID, ".md")
		c := &Concept{
			ID:          cleanID,
			Path:        cleanID + ".md",
			Type:        conceptType,
			Title:       strings.TrimSpace(title),
