		if hasType {
			conceptType, err = getStringArg(callParams.Arguments, "type", 1000, true)
			if err != nil {
				s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
				return
			}
			if strings.TrimSpace(conceptType) == "" {
