			}
			return nil
		})
		if err != nil {
			if errors.Is(err, ErrConceptNotFound) {
				s.sendToolResult(req.ID, fmt.Sprintf("Concept '%s' not found in %s", cleanID, bundleDir), nil, true)
				return
			}
			s.sendToolResult(req.ID, fmt.Sprintf("Failed to update concept: %v", err), nil, true)
