		s.sendToolResult(req.ID, msg, structured, false)

	case "okf_relate":
		srcID, err := getStringArg(callParams.Arguments, "source_id", 1000, true)
		if err != nil {
			s.sendToolResult(req.ID, fmt.Sprintf("Invalid arguments: %v", err), nil, true)
