106	func appendLogEntryLocked(bundleDir, entryType, description string) error {
107		entryType = strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(entryType, "\r", " "), "\n", " "))
108		description = strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(description, "\r", " "), "\n", " "))
109	
110		logPath := filepath.Join(bundleDir, "log.md")
111		if _, err := ensureWithinRoot(bundleDir, logPath); err != nil {
112			return err
113		}
114		today := time.Now().UTC().Format("2006-01-02")
115		newEntry := fmt.Sprintf("* **%s**: %s\n", entryType, description)
116	
117		existingContent := ""
118		// #nosec G304 -- logPath is guaranteed within bundleDir via ensureWithinRoot
119		if data, err := os.ReadFile(logPath); err == nil {
120			existingContent = string(data)
121		}
122	
123		heading := fmt.Sprintf("## %s\n", today)
124		if idx := strings.Index(existingContent, heading); idx != -1 {
125			afterHeading := existingContent[idx+len(heading):]
126			nextHeadingIdx := strings.Index(afterHeading, "\n## ")
127			todaySection := afterHeading
128			if nextHeadingIdx != -1 {
129				todaySection = afterHeading[:nextHeadingIdx]
130			}
131	
132			targetEntry := strings.TrimSpace(newEntry)
133			for _, line := range strings.Split(todaySection, "\n") {
134				if strings.TrimSpace(line) == targetEntry {
135					// Exact entry already recorded today; avoid redundant duplicate lines
136					return nil
137				}
138			}
139	
140			existingContent = existingContent[:idx+len(heading)] + newEntry + existingContent[idx+len(heading):]
141		} else {
142			// Prepend today heading
143			existingContent = heading + newEntry + "\n" + strings.TrimLeft(existingContent, "\n")
144		}
145	
146		// #nosec G703 -- logPath is validated and contained within bundle root
147		return atomicWriteFile(logPath, []byte(existingContent), 0o644)
148	}
