150	// ValidateConceptID verifies that a concept ID conforms to OKF naming conventions
151	// and does not attempt path traversal or target reserved bundle files.
152	func ValidateConceptID(id string) error {
153		trimmed := strings.TrimSpace(id)
154		if trimmed == "" {
155			return fmt.Errorf("concept ID cannot be empty")
156		}
157	
158		for _, r := range trimmed {
159			if unicode.IsControl(r) {
160				return fmt.Errorf("concept ID %q contains forbidden control character U+%04X", id, r)
161			}
162			if unicode.In(r, unicode.Cf) {
163				return fmt.Errorf("concept ID %q contains forbidden format/invisible character U+%04X", id, r)
164			}
165			if (r >= 0x202A && r <= 0x202E) || (r >= 0x2066 && r <= 0x2069) {
166				return fmt.Errorf("concept ID %q contains forbidden bidirectional override character U+%04X", id, r)
167			}
168			if !unicode.IsPrint(r) {
169				return fmt.Errorf("concept ID %q contains non-printable character U+%04X", id, r)
170			}
171		}
172	
173		cleanID := strings.TrimSuffix(trimmed, ".md")
174		if cleanID == "" || cleanID == "." || cleanID == ".." {
175			return fmt.Errorf("invalid concept ID %q", id)
176		}
177	
178		if strings.HasPrefix(cleanID, "-") {
179			return fmt.Errorf("concept ID %q cannot start with a hyphen -", id)
180		}
181	
182		if IsAbsPath(cleanID) {
183			return fmt.Errorf("concept ID %q must be a relative path", id)
184		}
185	
186		// Split by '/' or '\' and inspect each path component
187		parts := strings.FieldsFunc(cleanID, func(r rune) bool {
188			return r == '/' || r == '\\'
189		})
190	
191		if slices.Contains(parts, "..") {
192			return fmt.Errorf("concept ID %q contains forbidden '..' traversal", id)
193		}
194	
195		if len(parts) > MaxConceptDirectoryDepth {
196			return fmt.Errorf("concept ID %q exceeds maximum directory depth of %d", id, MaxConceptDirectoryDepth)
197		}
198	
199		for _, part := range parts {
200			if part != "." && strings.HasPrefix(part, ".") {
201				return fmt.Errorf("concept ID %q cannot contain hidden directory or dot-file component %q", id, part)
202			}
203		}
204	
205		// Clean path and ensure it does not escape
206		cleaned := filepath.Clean(strings.ReplaceAll(cleanID, "\\", "/"))
207		if cleaned == ".." || strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) {
208			return fmt.Errorf("concept ID %q escapes bundle directory", id)
209		}
210	
211		// Check for reserved filenames (index.md anywhere, root log.md, root AGENTS.md)
212		base := filepath.Base(cleaned)
213		normClean := strings.ReplaceAll(cleaned, "\\", "/")
214		if strings.EqualFold(base, "index") || strings.EqualFold(base, "index.md") ||
215			strings.EqualFold(normClean, "log") || strings.EqualFold(normClean, "log.md") ||
216			strings.EqualFold(normClean, "AGENTS") || strings.EqualFold(normClean, "AGENTS.md") {
217			return fmt.Errorf("concept ID %q is a reserved bundle document", id)
218		}
219	
220		return nil
221	}
